// Package storage keeps regions in WorldGuard's YAML layout:
// worlds/<world>/regions.yml under the plugin's folder.
package storage

import (
	"fmt"
	"log/slog"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"sync"

	"github.com/golem-mc/golem/plugin"
	"github.com/golem-mc/worldguard"
	"github.com/golem-mc/worldguard/internal/yamlfile"
	"github.com/google/uuid"
	"go.yaml.in/yaml/v4"
)

// fileHeader is WorldGuard's regions.yml header. WorldGuard:
// YamlRegionFile.FILE_HEADER
const fileHeader = `#
# WorldGuard regions file
#
# WARNING: THIS FILE IS AUTOMATICALLY GENERATED. If you modify this file by
# hand, be aware that A SINGLE MISTYPED CHARACTER CAN CORRUPT THE FILE. If
# WorldGuard is unable to parse the file, your regions will FAIL TO LOAD and
# the contents of this file will reset. Please use a YAML validator such as
# http://yaml-online-parser.appspot.com (for smaller files).
#
# REMEMBER TO KEEP PERIODICAL BACKUPS.
#`

// saveMu serialises every save, as WorldGuard locks the class.
var saveMu sync.Mutex

// Driver opens the region files under a worlds folder. WorldGuard:
// DirectoryYamlDriver
type Driver struct {
	Root string
	Log  *slog.Logger
}

// Get answers the store of the world named name.
func (d Driver) Get(name string) *File {
	return &File{name: name, path: filepath.Join(d.Root, name, "regions.yml"), log: d.Log}
}

// All answers the stores of every world folder that has a regions.yml.
func (d Driver) All() []*File {
	entries, _ := os.ReadDir(d.Root)
	var out []*File
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		if st, err := os.Stat(filepath.Join(d.Root, e.Name(), "regions.yml")); err == nil && !st.IsDir() {
			out = append(out, d.Get(e.Name()))
		}
	}
	return out
}

// File is one world's regions.yml. WorldGuard: YamlRegionFile
type File struct {
	name, path string
	log        *slog.Logger
}

func (f *File) Name() string { return f.name }

// Path answers the file's path.
func (f *File) Path() string { return f.path }

func (f *File) warn(msg string, args ...any) {
	if f.log != nil {
		f.log.Warn(fmt.Sprintf(msg, args...))
	}
}

// LoadAll reads every region. A missing file has none; a region that does
// not read is skipped with a warning.
func (f *File) LoadAll(flags *worldguard.FlagRegistry) ([]*worldguard.Region, error) {
	doc, err := yamlfile.Load(f.path, false)
	if err != nil {
		return nil, fmt.Errorf("failed to load region data from '%s': %w", f.path, err)
	}
	raw, _ := doc.Get("regions")
	regions, _ := raw.(map[string]any)
	loaded := map[string]*worldguard.Region{}
	parents := map[*worldguard.Region]string{}
	for _, id := range slices.Sorted(maps.Keys(regions)) {
		node, _ := regions[id].(map[string]any)
		r, err := f.readRegion(id, node, flags)
		if err != nil {
			f.warn("%s for region '%s'!\nHere is what the region data looks like:\n\n%s\n", err, id, dump(node))
			continue
		}
		loaded[r.ID()] = r
		if p, ok := node["parent"]; ok && p != nil {
			parents[r] = fmt.Sprint(p)
		}
	}
	for _, r := range slices.SortedFunc(maps.Keys(parents), func(a, b *worldguard.Region) int {
		return strings.Compare(a.ID(), b.ID())
	}) {
		parent, ok := loaded[worldguard.NormalizeID(parents[r])]
		if !ok {
			f.warn("Unknown region parent: %s", parents[r])
			continue
		}
		if err := r.SetParent(parent); err != nil {
			f.warn("Circular inheritance detected! Can't set the parent of '%s' to parent '%s'", r.ID(), parent.ID())
		}
	}
	out := make([]*worldguard.Region, 0, len(loaded))
	for _, id := range slices.Sorted(maps.Keys(loaded)) {
		out = append(out, loaded[id])
	}
	return out, nil
}

type loadError string

func (e loadError) Error() string { return string(e) }

func (f *File) readRegion(id string, node map[string]any, flags *worldguard.FlagRegistry) (*worldguard.Region, error) {
	if node == nil {
		return nil, loadError("Undefined region type")
	}
	var r *worldguard.Region
	var err error
	switch typ, _ := node["type"].(string); typ {
	case "":
		return nil, loadError("Undefined region type")
	case "cuboid":
		lo, ok1 := vector(node["min"])
		hi, ok2 := vector(node["max"])
		if !ok1 || !ok2 {
			return nil, loadError("Unexpected missing value")
		}
		r, err = worldguard.NewCuboidRegion(id, lo, hi)
	case "poly2d":
		minY, ok1 := intOf(node["min-y"])
		maxY, ok2 := intOf(node["max-y"])
		if !ok1 || !ok2 {
			return nil, loadError("Unexpected missing value")
		}
		r, err = worldguard.NewPolygonRegion(id, points(node["points"]), minY, maxY)
	case "global":
		r, err = worldguard.NewGlobalRegion(id)
	default:
		return nil, loadError("Unknown region type")
	}
	if err != nil {
		return nil, loadError(err.Error())
	}
	priority, ok := intOf(node["priority"])
	if !ok {
		return nil, loadError("Unexpected missing value")
	}
	r.SetPriority(priority)
	if raw, ok := node["flags"].(map[string]any); ok {
		r.SetFlags(flags.Unmarshal(raw, true, f.log))
	}
	r.SetOwners(f.domain(node["owners"]))
	r.SetMembers(f.domain(node["members"]))
	return r, nil
}

// vector reads {x, y, z}, flooring each.
func vector(raw any) (plugin.BlockPos, bool) {
	m, ok := raw.(map[string]any)
	if !ok {
		return plugin.BlockPos{}, false
	}
	var v [3]int
	for i, k := range []string{"x", "y", "z"} {
		f, ok := floatOf(m[k])
		if !ok {
			return plugin.BlockPos{}, false
		}
		v[i] = int(floor(f))
	}
	return plugin.BlockPos{X: v[0], Y: v[1], Z: v[2]}, true
}

func floor(f float64) float64 {
	i := float64(int64(f))
	if f < i {
		return i - 1
	}
	return i
}

func floatOf(raw any) (float64, bool) {
	switch n := raw.(type) {
	case int:
		return float64(n), true
	case float64:
		return n, true
	case uint64:
		return float64(n), true
	}
	return 0, false
}

func intOf(raw any) (int, bool) {
	f, ok := floatOf(raw)
	return int(f), ok
}

func points(raw any) []worldguard.Point2D {
	list, _ := raw.([]any)
	var out []worldguard.Point2D
	for _, e := range list {
		m, _ := e.(map[string]any)
		x, ok1 := floatOf(m["x"])
		z, ok2 := floatOf(m["z"])
		if ok1 && ok2 {
			out = append(out, worldguard.Point2D{X: int(floor(x)), Z: int(floor(z))})
		}
	}
	return out
}

func stringList(raw any) []string {
	list, _ := raw.([]any)
	out := make([]string, 0, len(list))
	for _, e := range list {
		if e != nil {
			out = append(out, yamlfile.Stringify(e))
		}
	}
	return out
}

func (f *File) domain(raw any) *worldguard.Domain {
	d := worldguard.NewDomain()
	m, _ := raw.(map[string]any)
	for _, n := range stringList(m["players"]) {
		d.AddPlayerName(n)
	}
	for _, s := range stringList(m["unique-ids"]) {
		id, err := uuid.Parse(s)
		if err != nil {
			f.warn("Failed to parse UUID '%s'", s)
			continue
		}
		d.AddPlayer(id)
	}
	for _, g := range stringList(m["groups"]) {
		d.AddGroup(g)
	}
	return d
}

// dump answers a region's data as indented YAML for a warning.
func dump(node any) string {
	data, err := yaml.Marshal(node)
	if err != nil {
		return "\t<error while dumping object>"
	}
	lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
	return "\t" + strings.Join(lines, "\n\t")
}

// SaveAll replaces the file's regions.
func (f *File) SaveAll(regions []*worldguard.Region) error {
	saveMu.Lock()
	defer saveMu.Unlock()
	doc := yamlfile.New(f.path, false)
	doc.Compact = true
	doc.Header = fileHeader
	all := &yamlfile.Map{}
	for _, r := range regions {
		all.Put(r.ID(), regionNode(r))
	}
	doc.Set("regions", all)
	if err := doc.Save(); err != nil {
		return fmt.Errorf("failed to rename temporary regions file to %s: %w", f.path, err)
	}
	return nil
}

func regionNode(r *worldguard.Region) *yamlfile.Map {
	m := &yamlfile.Map{}
	switch r.Type() {
	case worldguard.RegionCuboid:
		m.Put("type", "cuboid")
		m.Put("min", pos(r.Min()))
		m.Put("max", pos(r.Max()))
	case worldguard.RegionPolygon:
		m.Put("type", "poly2d")
		m.Put("min-y", r.Min().Y)
		m.Put("max-y", r.Max().Y)
		var pts []any
		for _, p := range r.Points() {
			pts = append(pts, &yamlfile.Map{Keys: []string{"x", "z"}, Values: []any{p.X, p.Z}})
		}
		m.Put("points", pts)
	default:
		m.Put("type", "global")
	}
	m.Put("priority", r.Priority())
	m.Put("flags", worldguard.MarshalFlags(r.Flags()))
	m.Put("owners", domainNode(r.Owners()))
	m.Put("members", domainNode(r.Members()))
	if p := r.Parent(); p != nil {
		m.Put("parent", p.ID())
	}
	return m
}

func pos(p plugin.BlockPos) *yamlfile.Map {
	return &yamlfile.Map{Keys: []string{"x", "y", "z"}, Values: []any{p.X, p.Y, p.Z}}
}

func domainNode(d *worldguard.Domain) map[string]any {
	m := map[string]any{}
	add := func(key string, values []string) {
		if len(values) > 0 {
			list := make([]any, len(values))
			for i, v := range slices.Sorted(slices.Values(values)) {
				list[i] = v
			}
			m[key] = list
		}
	}
	add("players", d.Names())
	ids := d.UUIDs()
	strs := make([]string, len(ids))
	for i, id := range ids {
		strs[i] = id.String()
	}
	add("unique-ids", strs)
	add("groups", d.Groups())
	return m
}
